from pydantic import Field
from pydantic.dataclasses import dataclass
@dataclass
class Parent:
    x: int = Field()
@dataclass
class Child(Parent):
    pass
c = Child(**{'x': '3'})
print('Child', repr(c), 'x=', c.x)
assert c.x == 3
